-- Retail creature scaling correction (12.1.5)
-- Fixes old-world and legacy creatures that were incorrectly using ContentTuningID 5937
-- (MinLevelSquish 1, MaxLevelSquish 120), which made level-5 characters meet level 119-121 mobs.
--
-- Sources, in order:
--   1. hotfixes.creature_template_difficulty  (retail DB2 export)
--   2. TDB 12.1.0 fallback rows, embedded below because not every install keeps tdb1210_world
--   3. custom CoA entries, mapped from the nearest retail creature spawn (embedded below)
--
-- Only scaling columns are touched; loot, gold, flags, spawn data and custom modifiers stay intact.
-- A restart (not .reload) is required: LoadCreatureTemplateDifficulty() runs only at startup.
--
-- Rollback: restore all nine scaling columns from the matching backup table:
--   creature_template_difficulty_retail_bak_20261111 (hotfix set, when hotfixes DB exists)
--   creature_template_difficulty_tdb_bak_20261111    (TDB fallback set)
--   creature_template_difficulty_custom_bak_20261111 (custom CoA set)
-- Each backup is created before its update. The hotfix sync is skipped safely when
-- the server has no `hotfixes` database, so the embedded fallback rows still apply.


-- 1. Retail hotfix rows (the authoritative source). The core keeps them in a
-- separate hotfixes database; skip this block instead of failing on installs
-- that do not have that database.
SET @has_hotfixes = (
    SELECT COUNT(*)
    FROM `information_schema`.`tables`
    WHERE `table_schema` = 'hotfixes'
      AND `table_name` = 'creature_template_difficulty'
);

SET @sql = IF(@has_hotfixes > 0,
'CREATE TABLE IF NOT EXISTS `creature_template_difficulty_retail_bak_20261111` AS
SELECT w.*
FROM `creature_template_difficulty` w
JOIN `hotfixes`.`creature_template_difficulty` h
  ON h.`Entry` = w.`Entry` AND h.`DifficultyID` = w.`DifficultyID`
WHERE w.`LevelScalingDeltaMin` <> h.`LevelScalingDeltaMin`
   OR w.`LevelScalingDeltaMax` <> h.`LevelScalingDeltaMax`
   OR w.`ContentTuningID` <> h.`ContentTuningID`
   OR w.`HealthScalingExpansion` <> h.`HealthScalingExpansion`
   OR w.`HealthModifier` <> h.`HealthModifier`
   OR w.`ManaModifier` <> h.`ManaModifier`
   OR w.`ArmorModifier` <> h.`ArmorModifier`
   OR w.`DamageModifier` <> h.`DamageModifier`
   OR w.`CreatureDifficultyID` <> h.`CreatureDifficultyID`',
'SELECT 1');
PREPARE `stmt` FROM @sql;
EXECUTE `stmt`;
DEALLOCATE PREPARE `stmt`;

SET @sql = IF(@has_hotfixes > 0,
'UPDATE `creature_template_difficulty` w
JOIN `hotfixes`.`creature_template_difficulty` h
  ON h.`Entry` = w.`Entry` AND h.`DifficultyID` = w.`DifficultyID`
SET w.`LevelScalingDeltaMin` = h.`LevelScalingDeltaMin`,
    w.`LevelScalingDeltaMax` = h.`LevelScalingDeltaMax`,
    w.`ContentTuningID` = h.`ContentTuningID`,
    w.`HealthScalingExpansion` = h.`HealthScalingExpansion`,
    w.`HealthModifier` = h.`HealthModifier`,
    w.`ManaModifier` = h.`ManaModifier`,
    w.`ArmorModifier` = h.`ArmorModifier`,
    w.`DamageModifier` = h.`DamageModifier`,
    w.`CreatureDifficultyID` = h.`CreatureDifficultyID`
WHERE w.`LevelScalingDeltaMin` <> h.`LevelScalingDeltaMin`
   OR w.`LevelScalingDeltaMax` <> h.`LevelScalingDeltaMax`
   OR w.`ContentTuningID` <> h.`ContentTuningID`
   OR w.`HealthScalingExpansion` <> h.`HealthScalingExpansion`
   OR w.`HealthModifier` <> h.`HealthModifier`
   OR w.`ManaModifier` <> h.`ManaModifier`
   OR w.`ArmorModifier` <> h.`ArmorModifier`
   OR w.`DamageModifier` <> h.`DamageModifier`
   OR w.`CreatureDifficultyID` <> h.`CreatureDifficultyID`',
'SELECT 1');
PREPARE `stmt` FROM @sql;
EXECUTE `stmt`;
DEALLOCATE PREPARE `stmt`;

-- 2. Retail entries missing from the hotfix export, from clean TDB 12.1.0.
DROP TEMPORARY TABLE IF EXISTS `tmp_retail_tdb_scaling_20261111`;
CREATE TEMPORARY TABLE `tmp_retail_tdb_scaling_20261111` (
  `Entry` int unsigned NOT NULL,
  `DifficultyID` int NOT NULL,
  `LevelScalingDeltaMin` smallint NOT NULL,
  `LevelScalingDeltaMax` smallint NOT NULL,
  `ContentTuningID` int NOT NULL,
  `HealthScalingExpansion` int NOT NULL,
  `HealthModifier` float NOT NULL,
  `ManaModifier` float NOT NULL,
  `ArmorModifier` float NOT NULL,
  `DamageModifier` float NOT NULL,
  `CreatureDifficultyID` int NOT NULL,
  PRIMARY KEY (`Entry`,`DifficultyID`)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `creature_template_difficulty_tdb_bak_20261111` AS
SELECT w.*
FROM `creature_template_difficulty` w
JOIN `tmp_retail_tdb_scaling_20261111` t ON t.`Entry` = w.`Entry` AND t.`DifficultyID` = w.`DifficultyID`;

UPDATE `creature_template_difficulty` w
JOIN `tmp_retail_tdb_scaling_20261111` t ON t.`Entry` = w.`Entry` AND t.`DifficultyID` = w.`DifficultyID`
SET w.`LevelScalingDeltaMin` = t.`LevelScalingDeltaMin`,
    w.`LevelScalingDeltaMax` = t.`LevelScalingDeltaMax`,
    w.`ContentTuningID` = t.`ContentTuningID`,
    w.`HealthScalingExpansion` = t.`HealthScalingExpansion`,
    w.`HealthModifier` = t.`HealthModifier`,
    w.`ManaModifier` = t.`ManaModifier`,
    w.`ArmorModifier` = t.`ArmorModifier`,
    w.`DamageModifier` = t.`DamageModifier`,
    w.`CreatureDifficultyID` = t.`CreatureDifficultyID`;

-- 3. Custom CoA entries: nearest retail spawn tuning; custom modifiers preserved.
DROP TEMPORARY TABLE IF EXISTS `tmp_custom_scaling_20261111`;
CREATE TEMPORARY TABLE `tmp_custom_scaling_20261111` (
  `Entry` int unsigned NOT NULL,
  `DifficultyID` int NOT NULL,
  `LevelScalingDeltaMin` smallint NOT NULL,
  `LevelScalingDeltaMax` smallint NOT NULL,
  `ContentTuningID` int NOT NULL,
  `HealthScalingExpansion` int NOT NULL,
  `HealthModifier` float NOT NULL,
  `ManaModifier` float NOT NULL,
  `ArmorModifier` float NOT NULL,
  `DamageModifier` float NOT NULL,
  `CreatureDifficultyID` int NOT NULL,
  PRIMARY KEY (`Entry`,`DifficultyID`)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `creature_template_difficulty_custom_bak_20261111` AS
SELECT w.*
FROM `creature_template_difficulty` w
JOIN `tmp_custom_scaling_20261111` t ON t.`Entry` = w.`Entry` AND t.`DifficultyID` = w.`DifficultyID`;

UPDATE `creature_template_difficulty` w
JOIN `tmp_custom_scaling_20261111` t ON t.`Entry` = w.`Entry` AND t.`DifficultyID` = w.`DifficultyID`
SET w.`LevelScalingDeltaMin` = t.`LevelScalingDeltaMin`,
    w.`LevelScalingDeltaMax` = t.`LevelScalingDeltaMax`,
    w.`ContentTuningID` = t.`ContentTuningID`,
    w.`HealthScalingExpansion` = t.`HealthScalingExpansion`,
    w.`HealthModifier` = t.`HealthModifier`,
    w.`ManaModifier` = t.`ManaModifier`,
    w.`ArmorModifier` = t.`ArmorModifier`,
    w.`DamageModifier` = t.`DamageModifier`,
    w.`CreatureDifficultyID` = t.`CreatureDifficultyID`;

-- Verification: after restart, inspect a level-5 Durotar character and a level-60
-- character. Old-world mobs must no longer be 119-121. A few 12.1 map-2694 creatures
-- legitimately keep ContentTuningID 5937 in the retail export.
